<?php
/**
 * Ensures wpswup-fa_IR.mo exists (binary cannot always be committed via all workflows).
 * Loaded early from wpswup.php if needed.
 */
defined( 'ABSPATH' ) || exit;

$mo = SLL_DIR . 'languages/wpswup-fa_IR.mo';
if ( ! file_exists( $mo ) || filesize( $mo ) < 100 ) {
	$b64 = '';
	$bin = base64_decode( $b64, true );
	if ( is_string( $bin ) && strlen( $bin ) > 100 ) {
		// phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_file_put_contents
		file_put_contents( $mo, $bin );
	}
}
